_named() {
    # check if -named option has been requested
    for opt in ${COMP_LINE}; do
        [[ "$opt" == "-named" ]] && return 0
    done
    return 1
}

_method() {
    # return rpc method (first non option argument)
    local arg
    for arg in "${words[@]:1}"; do
        [[ $arg != -* ]] && {
            echo "$arg"
            return 0
        }
    done
    return 1
}

