_bitcoin_cli() {
    # main handler
    local cur prev words=() cword
    COMPREPLY=()
    _get_comp_words_by_ref -n = cur prev words cword
    local method
    method=$(_method)

    # Named mode: typing a global option (starts with -)
    if _named && [[ "$cur" == -* ]]; then
        COMPREPLY=( $( compgen -W "${helpopts[*]}" -- "$cur" ) )
        return
    fi

    # Named mode: typing (or completing) the method name
    if _named && [[ "$cur" == "$method" ]]; then
        COMPREPLY=( $( compgen -W "${helpopts[*]} ${methods[*]}" -- "$cur" ) )
        return
    fi

    # Named mode: typing named parameters for the method
    if _named; then
        _bitcoin_cli_named
        [[ $COMPREPLY == *= ]] && compopt -o nospace
        return
    fi

    # Positional mode: delegate to positional handler
    _bitcoin_cli_positional
    [[ ${#COMPREPLY[@]} -gt 0 || (-n "$method" && "$method" != "$cur") ]] && return

    case "$cur" in
        -conf=*)
            cur="${cur#*=}"
            _filedir
            return 0
            ;;
        -datadir=*)
            cur="${cur#*=}"
            _filedir -d
            return 0
            ;;
        -*=*) # prevent nonsense completions
            return 0
            ;;
        *)
            COMPREPLY=( $( compgen -W "${helpopts[*]} ${methods[*]}" -- "$cur" ) )
            # Prevent space if an argument is desired
            if [[ $COMPREPLY == *= ]]; then
                compopt -o nospace
            fi
            return 0
            ;;
    esac
} &&
complete -F _bitcoin_cli bitcoin-cli
